param(
    [string]$ProjectRoot = ".",
    [switch]$Build
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$root = (Resolve-Path $ProjectRoot).Path
$target = Join-Path $root "src\CompanyDlp.Service\SoftwareProtectionMonitor.cs"
$solution = Join-Path $root "CompanyDlp.sln"

if (-not (Test-Path $target)) {
    throw "SoftwareProtectionMonitor.cs was not found under: $root"
}

$backup = "$target.before-user-sid-hotfix.bak"
if (-not (Test-Path $backup)) {
    Copy-Item $target $backup -Force
    Write-Host "Created backup: $backup"
}

$base64 = @'

'@

$bytes = [Convert]::FromBase64String(($base64 -replace "\s", ""))
[System.IO.File]::WriteAllBytes($target, $bytes)

Write-Host "Applied software.install UserSid fallback hotfix."
Write-Host "Updated: $target"

if ($Build) {
    if (-not (Test-Path $solution)) {
        throw "CompanyDlp.sln was not found under: $root"
    }

    Push-Location $root
    try {
        & dotnet build $solution --configuration Release --no-restore
        $buildExitCode = $LASTEXITCODE
        if ($buildExitCode -ne 0) {
            throw "dotnet build failed with exit code $buildExitCode."
        }
    }
    finally {
        Pop-Location
    }

    Write-Host "Build succeeded."
}

Write-Host "Restart START_DEVELOPMENT.bat before retesting software.install."
